import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const c="data:image/png;base64,",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"快速入门","link":"/guide/getting_started/quick_start/heterogeneous_system_and_programming_model"},{"text":"基于SIMD编程","link":"/guide/getting_started/quick_start/simd_programming/simd_programming"},{"text":"Add算子快速入门","link":"/guide/getting_started/quick_start/simd_programming/add_op_quick_start"}]},"headers":[],"relativePath":"guide/getting_started/quick_start/simd_programming/add_op_quick_start.md","filePath":"guide/getting_started/quick_start/simd_programming/add_op_quick_start.md","lastUpdated":1787050286000}'),t={name:"guide/getting_started/quick_start/simd_programming/add_op_quick_start.md"};function e(o,s,i,d,r,_){return n(),p("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>Add算子快速入门<span id="ZH-CN_TOPIC_0000002500781060"></span></h1><p>本示例是一个入门实践，基于Ascend C SIMD实现Add算子，帮助您快速上手。它完整呈现了Device端核函数（Kernel）实现、Host端调用及编译运行的全流程，助您建立整体认知。开始前，请先参考<a href="../../environment_setup.html">环境准备</a>安装所需的CANN软件包。</p><p>下面分别介绍基于C API与C++ API的Add算子实现，完整示例代码请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/00_introduction/01_add/c_api_async_add/README.md">基于C API实现的Add算子示例</a>和<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/00_introduction/01_add/add/README.md">基于C++ API实现的Add算子示例</a>。</p><ul><li><p><strong>Add算子功能介绍</strong>：</p><p>Add算子的数学表达式为：</p><p><img src="'+c+`" alt></p><p>计算逻辑为逐元素完成<code>z = x + y</code>。</p></li><li><p><strong>算子设计</strong></p><ul><li><p><strong>Device端核函数（Kernel）编程接口</strong></p><ul><li>核函数（Kernel）定义：通过 <a href="../../../programming_guide/language_extension/simd_builtin_keywords.html">__global__</a>修饰符声明。</li><li>数据分块（Tiling）：使用内置关键字 <a href="../../../programming_guide/language_extension/simd_builtin_keywords.html">block_idx</a>确定每个Block负责处理的数据。</li><li>数据搬入：通过<a href="../../../programming_guide/language_extension/simd_language_extension_c_api.html">C API接口</a> <code>asc_copy_gm2ub</code>或<a href="../../../programming_guide/library_api/programming_interface_overview.html">C++接口</a> <code>AscendC::DataCopy</code>完成。</li><li>数据计算：通过C API接口<code>asc_add</code>或C++接口<code>AscendC::Add</code>完成。</li><li>数据搬出：通过C API接口<code>asc_copy_ub2gm</code>或C++接口<code>AscendC::DataCopy</code>完成。</li></ul></li><li><p><strong>Host端运行时接口</strong></p><ul><li>内存分配：使用<code>aclrtMallocHost</code>分配Host Memory，<code>aclrtMalloc</code>分配Device Memory。</li><li>数据搬入：使用<code>aclrtMemcpy</code>将输入数据从Host Memory拷贝到Device Memory。</li><li>启动NPU计算任务：通过<code>&lt;&lt;&lt;...&gt;&gt;&gt;</code>语法糖启动核函数（Kernel）。</li><li>同步等待：调用<code>aclrtSynchronizeStream</code>或<code>aclrtSynchronizeDevice</code>等待任务完成。</li><li>数据搬出：使用<code>aclrtMemcpy</code>将计算结果从Device Memory拷贝回Host Memory。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>请参见<a href="../../ascend_c_overview_and_learning_path.html">Ascend-C概述与学习路径</a>技术附录章节，获取<code>Ascend C API参考</code>和<code>CANN运行时接口</code>链接，以查阅更多接口信息。</li></ul></div></li></ul></li><li><p><strong>算子代码实现</strong>：</p><p>后缀名为<code>*.asc</code>的代码文件包含Host端与Device端代码。</p><ul><li><p><strong>Device端核函数（Kernel）实现</strong>： Device端部分示例如下：</p><ul><li><p><strong>基于C语言API实现Memory矢量计算示例</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__vector__</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">asc_init</span><span class="p">();</span>

<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">block_length</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">TOTAL_LENGTH</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">NUM_BLOCKS</span><span class="p">;</span>
<span class="w">    </span>
<span class="w">    </span><span class="c1">// Determine the data that each block needs to process</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">x_gm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">block_length</span><span class="p">;</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">y_gm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">y</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">block_length</span><span class="p">;</span>
<span class="w">    </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">z_gm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">z</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">block_length</span><span class="p">;</span>

<span class="w">    </span><span class="c1">// Allocate on-chip Unified Buffer（UB） memory</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">x_local</span><span class="p">[</span><span class="n">block_length</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">y_local</span><span class="p">[</span><span class="n">block_length</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">z_local</span><span class="p">[</span><span class="n">block_length</span><span class="p">];</span>

<span class="w">    </span><span class="c1">// Copy input data from Global Memory (i.e., Device Memory) to on-chip UB memory</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub</span><span class="p">(</span><span class="n">x_local</span><span class="p">,</span><span class="w"> </span><span class="n">x_gm</span><span class="p">,</span><span class="w"> </span><span class="n">block_length</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">));</span>
<span class="w">    </span><span class="n">asc_copy_gm2ub</span><span class="p">(</span><span class="n">y_local</span><span class="p">,</span><span class="w"> </span><span class="n">y_gm</span><span class="p">,</span><span class="w"> </span><span class="n">block_length</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">));</span>
<span class="w">    </span><span class="n">asc_sync</span><span class="p">();</span>

<span class="w">    </span><span class="c1">// Call SIMD API to complete the Add operation</span>
<span class="w">    </span><span class="n">asc_add</span><span class="p">(</span><span class="n">z_local</span><span class="p">,</span><span class="w"> </span><span class="n">x_local</span><span class="p">,</span><span class="w"> </span><span class="n">y_local</span><span class="p">,</span><span class="w"> </span><span class="n">block_length</span><span class="p">);</span>
<span class="w">    </span><span class="n">asc_sync</span><span class="p">();</span>

<span class="w">    </span><span class="c1">// Write the result from on-chip UB memory back to Global Memory</span>
<span class="w">    </span><span class="n">asc_copy_ub2gm</span><span class="p">(</span><span class="n">z_gm</span><span class="p">,</span><span class="w"> </span><span class="n">z_local</span><span class="p">,</span><span class="w"> </span><span class="n">block_length</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="k">sizeof</span><span class="p">(</span><span class="kt">float</span><span class="p">));</span>
<span class="w">    </span><span class="n">asc_sync</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>本Memory矢量计算示例支持以下型号： <div data-filter="A3"><ul><li>Atlas A3训练系列产品/Atlas A3推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2训练系列产品/Atlas A2推理系列产品</li></ul></div></li><li>SIMD算子的核函数（Kernel）需要额外修饰符，<a href="../../../programming_guide/language_extension/simd_builtin_keywords.html"><code>__vector__</code></a>修饰符表明该算子仅在向量计算单元上执行。</li><li><strong>性能提示</strong>：示例中为简化同步操作，统一使用了 <code>asc_sync</code>。在实际算子开发中，建议根据流水线执行情况使用具体的同步控制指令，以获得更好的性能。详见<a href="../../../programming_guide/programming_model/ai_core_simd_programming/c_pointer_programming/c_programming_overview.html#%E5%90%8C%E6%AD%A5%E6%9C%BA%E5%88%B6">同步机制</a>章节。</li></ul></div></li><li><p><strong>基于C++ Tensor实现Memory矢量计算示例</strong></p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">blockLength</span><span class="o">&gt;</span>
<span class="n">__vector__</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">z</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">InitSocState</span><span class="p">();</span>
<span class="w">    </span>
<span class="w">    </span><span class="c1">// Determine the data that each block needs to process</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">xGm</span><span class="p">,</span><span class="w"> </span><span class="n">yGm</span><span class="p">,</span><span class="w"> </span><span class="n">zGm</span><span class="p">;</span>
<span class="w">    </span><span class="n">xGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span><span class="n">x</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockLength</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">yGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span><span class="n">y</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockLength</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">zGm</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span><span class="n">z</span><span class="w"> </span><span class="o">+</span><span class="w"> </span><span class="n">block_idx</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">blockLength</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span>
<span class="w">    </span><span class="c1">// Allocate on-chip UB memory</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalMemAllocator</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">Hardware</span><span class="o">::</span><span class="n">UB</span><span class="o">&gt;</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">xLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">yLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="w"> </span><span class="n">zLocal</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ubAllocator</span><span class="p">.</span><span class="n">Alloc</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span>
<span class="w">    </span><span class="c1">// Copy input data from Global Memory (i.e., Device Memory) to on-chip UB memory</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xGm</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yGm</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span>
<span class="w">    </span><span class="c1">// Call SIMD API to complete the Add operation</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">Add</span><span class="p">(</span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">xLocal</span><span class="p">,</span><span class="w"> </span><span class="n">yLocal</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span>
<span class="w">    </span><span class="c1">// Write the result from on-chip UB memory back to Global Memory</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DataCopy</span><span class="p">(</span><span class="n">zGm</span><span class="p">,</span><span class="w"> </span><span class="n">zLocal</span><span class="p">,</span><span class="w"> </span><span class="n">blockLength</span><span class="p">);</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">PipeBarrier</span><span class="o">&lt;</span><span class="n">PIPE_ALL</span><span class="o">&gt;</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>该样例支持以下型号： <div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div><div data-filter="A3"><ul><li>Atlas A3训练系列产品/Atlas A3推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2训练系列产品/Atlas A2推理系列产品</li></ul></div></li><li>SIMD算子的核函数（Kernel）需要额外修饰符，<a href="../../../programming_guide/language_extension/simd_builtin_keywords.html"><code>__vector__</code></a>修饰符表明该算子仅在向量计算单元上执行。</li></ul></div></li></ul></li><li><p><strong>Host端代码实现</strong>：</p><p>Host端通过<code>&lt;&lt;&lt;&gt;&gt;&gt;</code>语法糖调用Device端核函数（Kernel），示例代码片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="kt">int32_t</span><span class="w"> </span><span class="nf">main</span><span class="p">(</span><span class="kt">int</span><span class="w"> </span><span class="n">argc</span><span class="p">,</span><span class="w"> </span><span class="kt">char</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="o">*</span><span class="n">argv</span><span class="p">[])</span>
<span class="w">  </span><span class="p">{</span>
<span class="w">      </span><span class="p">...</span>
<span class="w">      </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">numBlocks</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="w">      </span><span class="p">...</span>

<span class="w">      </span><span class="c1">// Create runtime stream by aclrtCreateStream API</span>
<span class="w">      </span><span class="n">aclrtStream</span><span class="w"> </span><span class="n">stream</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">nullptr</span><span class="p">;</span>
<span class="w">      </span><span class="n">aclrtCreateStream</span><span class="p">(</span><span class="o">&amp;</span><span class="n">stream</span><span class="p">);</span>
<span class="w">      </span>
<span class="w">      </span><span class="c1">// Allocate host and device memory, and copy input data from host to device</span>
<span class="w">      </span><span class="n">aclrtMalloc</span><span class="p">((</span><span class="kt">void</span><span class="o">**</span><span class="p">)</span><span class="o">&amp;</span><span class="n">xDevice</span><span class="p">,</span><span class="w"> </span><span class="n">totalByteSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEM_MALLOC_HUGE_FIRST</span><span class="p">);</span>
<span class="w">      </span><span class="n">aclrtMalloc</span><span class="p">((</span><span class="kt">void</span><span class="o">**</span><span class="p">)</span><span class="o">&amp;</span><span class="n">yDevice</span><span class="p">,</span><span class="w"> </span><span class="n">totalByteSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEM_MALLOC_HUGE_FIRST</span><span class="p">);</span>
<span class="w">      </span><span class="n">aclrtMalloc</span><span class="p">((</span><span class="kt">void</span><span class="o">**</span><span class="p">)</span><span class="o">&amp;</span><span class="n">zDevice</span><span class="p">,</span><span class="w"> </span><span class="n">totalByteSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEM_MALLOC_HUGE_FIRST</span><span class="p">);</span>
<span class="w">      </span><span class="n">aclrtMallocHost</span><span class="p">((</span><span class="kt">void</span><span class="o">**</span><span class="p">)</span><span class="o">&amp;</span><span class="n">zHost</span><span class="p">,</span><span class="w"> </span><span class="n">totalByteSize</span><span class="p">);</span>

<span class="w">      </span><span class="n">aclrtMemcpy</span><span class="p">(</span><span class="n">xDevice</span><span class="p">,</span><span class="w"> </span><span class="n">totalByteSize</span><span class="p">,</span><span class="w"> </span><span class="n">x</span><span class="p">.</span><span class="n">data</span><span class="p">(),</span><span class="w"> </span><span class="n">totalByteSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEMCPY_HOST_TO_DEVICE</span><span class="p">);</span>
<span class="w">      </span><span class="n">aclrtMemcpy</span><span class="p">(</span><span class="n">yDevice</span><span class="p">,</span><span class="w"> </span><span class="n">totalByteSize</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">.</span><span class="n">data</span><span class="p">(),</span><span class="w"> </span><span class="n">totalByteSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEMCPY_HOST_TO_DEVICE</span><span class="p">);</span>

<span class="w">      </span><span class="c1">// Launch kernel &lt;&lt;&lt;numBlocks, dynUBufSize, stream&gt;&gt;&gt;</span>
<span class="w">      </span><span class="c1">// numBlocks : Number of blocks. Default to 8 in this example.</span>
<span class="w">      </span><span class="c1">// dynUBufSize : Dynamic unified buffer size. Default to 0 in this example.</span>
<span class="w">      </span><span class="c1">// stream : Runtime stream.</span>

<span class="w">      </span><span class="c1">// Example：Call add kernel which is implemented by SIMD C++ Basic API</span>
<span class="w">      </span><span class="n">add_custom</span><span class="o">&lt;</span><span class="n">blockLength</span><span class="o">&gt;&lt;&lt;&lt;</span><span class="n">numBlocks</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">stream</span><span class="o">&gt;&gt;&gt;</span><span class="p">(</span><span class="n">xDevice</span><span class="p">,</span><span class="w"> </span><span class="n">yDevice</span><span class="p">,</span><span class="w"> </span><span class="n">zDevice</span><span class="p">);</span>

<span class="w">      </span><span class="c1">// Wait for the add_custom kernel to complete</span>
<span class="w">      </span><span class="n">aclrtSynchronizeStream</span><span class="p">(</span><span class="n">stream</span><span class="p">);</span>

<span class="w">      </span><span class="c1">// Copy the result from device memory to host memory</span>
<span class="w">      </span><span class="n">aclrtMemcpy</span><span class="p">(</span><span class="n">zHost</span><span class="p">,</span><span class="w"> </span><span class="n">totalByteSize</span><span class="p">,</span><span class="w"> </span><span class="n">zDevice</span><span class="p">,</span><span class="w"> </span><span class="n">totalByteSize</span><span class="p">,</span><span class="w"> </span><span class="n">ACL_MEMCPY_DEVICE_TO_HOST</span><span class="p">);</span>
<span class="w">      </span><span class="p">...</span>
<span class="w">  </span><span class="p">}</span>
</code></pre></div></li></ul></li><li><p><strong>算子编译与运行</strong>：</p><p>CMake配置文件示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">CMake</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="nb">cmake_minimum_required</span><span class="p">(</span><span class="s">VERSION</span><span class="w"> </span><span class="s">3.16</span><span class="p">)</span>

<span class="nb">find_package</span><span class="p">(</span><span class="s">ASC</span><span class="w"> </span><span class="s">REQUIRED</span><span class="p">)</span>

<span class="nb">project</span><span class="p">(</span><span class="s">kernel_samples</span><span class="w"> </span><span class="s">LANGUAGES</span><span class="w"> </span><span class="s">ASC</span><span class="w"> </span><span class="s">CXX</span><span class="p">)</span>

<span class="nb">add_executable</span><span class="p">(</span><span class="s">c_api_add_example</span>
<span class="w">    </span><span class="s">c_api_add.asc</span>
<span class="p">)</span>

<span class="c"># ======================================================================================</span>
<span class="c"># NPU编译选项配置</span>
<span class="c">#</span>
<span class="c"># 说明：</span>
<span class="c">#   - 需根据实际部署的NPU硬件架构选择对应的\`npu-arch\`参数。</span>
<span class="c"># ======================================================================================</span>
<span class="nb">target_compile_options</span><span class="p">(</span><span class="s">c_api_add_example</span><span class="w"> </span><span class="s">PRIVATE</span>
<span class="w">    </span><span class="o">$&lt;</span><span class="nv">$&lt;COMPILE_LANGUAGE:ASC</span><span class="o">&gt;</span><span class="s">:--npu-arch=dav-2201&gt;</span>
<span class="p">)</span>
</code></pre></div><p>编译与执行示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">Bash</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>mkdir<span class="w"> </span>-p<span class="w"> </span>build<span class="w"> </span><span class="o">&amp;&amp;</span><span class="w"> </span><span class="nb">cd</span><span class="w"> </span>build<span class="p">;</span><span class="w">   </span><span class="c1"># 创建并进入build目录</span>
cmake<span class="w"> </span>..<span class="p">;</span>make<span class="w"> </span>-j<span class="p">;</span><span class="w">             </span><span class="c1"># 编译工程</span>
./c_api_add_example<span class="w">           </span><span class="c1"># 运行样例</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>编译选项<code>--npu-arch</code>用于指定NPU架构版本，<code>dav-</code>后面的数字为架构版本号，请替换为您实际使用的版本。各AI处理器型号与架构版本的对应关系请查阅<a href="../../../programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">AI处理器型号和 __NPU_ARCH__ 的对应关系</a>。</li></ul></div></li></ul><p>此外，基于C/C++不同层级的编程接口和不同的矢量计算类型，Add算子有多种实现方式，具体可参考下表：</p><table><thead><tr><th>API层级</th><th>矢量计算类型</th><th>Add算子实例</th><th>说明</th></tr></thead><tbody><tr><td>SIMD C API</td><td>基于指针的Memory矢量计算</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/00_introduction/01_add/c_api_async_add/README.md">Memory矢量计算Add算子示例（同上述C API实现样例）</a></td><td>贴合C语言开发习惯，易于上手</td></tr><tr><td>SIMD C API</td><td>基于指针和Reg计算的Reg矢量计算</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/02_simd_c_api/00_introduction/04_reg_base_add_compute/c_api_simd_add/README.md">Reg矢量计算Add算子示例</a></td><td>贴合C语言开发习惯，性能上限更高</td></tr><tr><td>基础API</td><td>基于Tensor的Memory矢量计算</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/00_introduction/01_add/add/README.md">Memory矢量计算Add算子示例（同上述C++ Tensor实现样例）</a></td><td>匹配Tensor编程习惯，易于上手</td></tr><tr><td>基础API</td><td>基于Tensor的Reg矢量计算</td><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/00_introduction/04_reg_compute/add/README.md">Reg矢量计算Add算子示例</a></td><td>匹配Tensor编程习惯，性能上限更高</td></tr></tbody></table><div data-filter="950"><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>Ascend 950PR/Ascend 950DT新一代架构在传统<a href="../../../technical_appendix/concepts_and_terms/glossary.html">UB</a>缓存体系的基础上，开放了寄存器（Register）可编程能力，单个寄存器大小为256B。基于寄存器的矢量计算称为Reg矢量计算，而基于传统UB的矢量计算称为Memory矢量计算。</p></div></div><p>若要深入理解Ascend C的SIMD与SIMT编程模型，请参阅<a href="../../../programming_guide/programming_model/programming_model_overview.html">Ascend C编程模型概述</a>。</p></article></div>`,1)])])}const g=a(t,[["render",e]]);export{m as __pageData,g as default};
